const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function completionReviewPanel(review,{busy=false,dirty=false,actions=true}={}){
 if(!review||review.status==='generating')return '';
 const legacyExpressions=review.suggestions||[],changed=review.basisChanged||dirty,confirmed=review.status==='confirmed'&&!changed&&!legacyExpressions.length,ready=review.status==='ready'&&!changed&&!legacyExpressions.length,unavailable=review.reasonCode==='check_unavailable';
 const title=dirty?'资料有修改，尚未保存':changed?'资料已保存，正文待更新':unavailable?'本版检查尚未完成':confirmed?'补充内容已确认':ready?'自动补充完成，请确认内容':review.status==='needs_materials'?'已补充可完成内容，仍需核实资料':'自动补充结果待继续检查';
 const explanation=dirty?'本页修改尚未保存，请使用下方按钮保存材料并自动完善正文。':changed?'新资料尚未写入当前正文，旧检查结果已失效。请使用下方按钮，按已补充资料完善正文并重新检查。':'补充后的内容已写入正文，可在下方预览，原有版本保留。请核对研究事实、数据含义与引用。';
 const footer=changed?'已有资料无需重复上传，请使用已补充资料更新正文。':unavailable?'检查没有完整结束，不能据此认定补充资料不足。已保存的资料和正文保留，继续完善后重新检查。':review.missing?.length?'仍需确认的具体信息已列在上方，当前正文可以下载为初稿。':'当前正文仍有待处理的检查项，继续自动完善并检查即可；当前结果可下载为初稿。';
 const sim=review.simulation,simNote=sim?.savedCount?`<p class="completion-simulation-note">模拟数据已保存 ${Number(sim.records)||0} 条；${sim.usedCount?'已写入正文，'+(sim.checked?'本版资料检查已完成。':'等待本版检查完成。'):'尚未写入当前正文，请使用已补充资料自动完善。'} 仿真方法和数据说明会保留。</p>`:review.simulationUsed?'<p class="completion-simulation-note">本稿使用了模拟数据，终稿将保留仿真方法与数据说明。</p>':'';
 return `<section class="thesis-completion-review" data-completion-review data-state="${confirmed?'confirmed':ready?'ready':'pending'}" aria-label="自动补充结果确认"><header><div><small>终稿内容确认</small><h3>${title}</h3></div><span>${(review.changes||[]).length} 个章节已更新</span></header><p>${explanation}</p>${simNote}<div class="completion-review-checks">${[['materials','资料依据'],['manuscript','全文检查'],['content','内容完整性']].map(([key,label])=>`<span data-passed="${!changed&&review.checks?.[key]===true}">${!changed&&review.checks?.[key]===true?'✓':'·'} ${label}</span>`).join('')}</div><ul class="completion-review-changes" aria-label="自动补充的章节">${(review.changes||[]).map(row=>`<li><div><b>${esc(row.title)}</b><small>${row.kind==='added'?'已补写':'已完善'} · ${Number(row.characters).toLocaleString('zh-CN')} 字符</small></div><button type="button" class="btn secondary" data-completion-view="${esc(row.chapterId)}" ${busy?'disabled':''}>查看内容</button></li>`).join('')}</ul>${(changed||unavailable)&&review.informationMissing?.length?`<div class="completion-review-missing"><strong>另外需要本人填写或提供的信息</strong><ul>${review.informationMissing.map(text=>`<li>${esc(text)}</li>`).join('')}</ul></div>`:''}${!changed&&!unavailable&&review.missing?.length?`<div class="completion-review-missing"><strong>仍需确认的事实资料</strong><p>这些事实无法从现有资料确定，补充后系统会继续写入正文。</p><ul>${review.missing.map(text=>`<li>${esc(text)}</li>`).join('')}</ul></div>`:''}${review.issues?.length?`<details open><summary>待完善的检查项</summary><ul>${review.issues.map(row=>`<li>${esc(row.title)}：${esc(row.text)}</li>`).join('')}</ul></details>`:''}${legacyExpressions.length?`<details open><summary>待自动修正的表达问题</summary><p>这些问题将由系统直接修改并复检，请继续自动补充。</p><ul>${legacyExpressions.map(row=>`<li>${esc(row.title)}：${esc(row.text)}</li>`).join('')}</ul></details>`:''}${ready&&actions?`<button type="button" class="btn primary" data-completion-confirm ${busy?'disabled':''}>确认补充内容，编排并导出终稿</button>`:confirmed?'<p role="status">本版本已确认，可在下方下载终稿。内容或模板变化后需重新确认。</p>':ready?'':`<p role="status">${footer}</p>`}<p data-completion-confirm-status role="status"></p></section>`;
}
